changeSet.sql:
CREATE TABLE IF NOT EXISTS "user".admin ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL, login VARCHAR(64) NOT NULL UNIQUE, password TEXT NOT NULL, role VARCHAR(32) NOT NULL, full_name VARCHAR(255),
is_active BOOLEAN DEFAULT TRUE, deleted BOOLEAN DEFAULT FALSE, created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT );
CREATE INDEX IF NOT EXISTS idx_admin_login ON "user".admin (login);
